#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <fcntl.h>
#include <errno.h>
#include <string.h>

// Define syncfs prototype if necessary, though generally included via unistd.h or sys/sync.h
// int syncfs(int fd);

int main(void) {
    const char *filename = "durable_data_volume_sync.tmp";
    const char *data = "This transactional log must be committed.";
    int fd;
    int ret;

    // 1. Open file (O_SYNC is avoided to test the explicit syncfs call)
    fd = open(filename, O_WRONLY | O_CREAT | O_TRUNC, 0644);
    if (fd == -1) {
        perror("Error opening file");
        return EXIT_FAILURE;
    }

    // 2. Write data (data is likely in kernel cache)
    if (write(fd, data, strlen(data)) == -1) {
        perror("Error writing data");
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Data written to buffer. Fd: %d.\n", fd);

    // 3. Force synchronization of the entire filesystem containing 'fd'
    printf("Forcing filesystem cache commit...\n");
    ret = syncfs(fd);

    if (ret == -1) {
        // Check errno for EBADF, EIO, ENOSPC, etc.
        fprintf(stderr, "Error during syncfs: %s\n", strerror(errno));
        close(fd);
        return EXIT_FAILURE;
    }

    printf("Filesystem synchronization successful. Data is durable.\n");

    // 4. Cleanup
    if (close(fd) == -1) {
        perror("Error closing file");
        return EXIT_FAILURE;
    }

    // Cleanup temporary file
    unlink(filename);

    return EXIT_SUCCESS;
}
